import{_ as E,C as h,o as a,c as i,a7 as t,b as s,w as r,a as n,E as A,a8 as l}from"./chunks/framework.BCbKzsgW.js";const f=JSON.parse('{"title":"密码、验证码与账号恢复","description":"","frontmatter":{"outline":"deep"},"headers":[],"relativePath":"development/common/authentication/password.md","filePath":"development/common/authentication/password.md","lastUpdated":1793703140000}'),d={name:"development/common/authentication/password.md"};function p(u,e,B,c,m,g){const o=h("Mermaid");return a(),i("div",null,[e[1]||(e[1]=t('<h1 id="mi-mayan-zheng-ma-yu-zhang-hao-hui-fu" tabindex="-1">密码、验证码与账号恢复 <a class="header-anchor" href="#mi-mayan-zheng-ma-yu-zhang-hao-hui-fu" aria-label="Permalink to &quot;密码、验证码与账号恢复&quot;">​</a></h1><p>密码登录的核心是验证用户输入与已保存凭据是否匹配。工程难点在于限制在线猜测、抵御数据库泄露后的离线破解，并让密码重置具备清晰的账号接管边界。</p><h2 id="mi-ma-ce-lue-yu-cun-chu" tabindex="-1">密码策略与存储 <a class="header-anchor" href="#mi-ma-ce-lue-yu-cun-chu" aria-label="Permalink to &quot;密码策略与存储&quot;">​</a></h2><p><a href="https://pages.nist.gov/800-63-4/sp800-63b.html#passwordver" target="_blank" rel="noreferrer">NIST SP 800-63B-4 §3.1.1</a>对其适用系统规定：单因素密码至少 15 个字符；仅用于多因素流程时可放宽到至少 8 个字符；支持的最大长度应至少达到 64 个字符。不要求混合字符类别，也不要求在没有泄露证据时周期性改密。普通业务可以参考这些原则，但不能仅满足几项长度规则就宣称达到某个认证保证等级。</p><p>实际产品还要支持密码管理器、粘贴与泄露密码拦截。密码不要自动去首尾空格，也不要静默截断；若采用 Unicode 规范化，注册、改密和验证必须使用同一约定。</p><p>密码使用专门的慢哈希算法。<a href="https://cheatsheetseries.owasp.org/cheatsheets/Password_Storage_Cheat_Sheet.html#argon2id" target="_blank" rel="noreferrer">OWASP Password Storage</a>优先建议 Argon2id，其中一组最低配置为内存 19 MiB、迭代 2、并行度 1。这是基线配置，不是所有部署的最终参数：需要在目标硬件、容器限制和并发量下测量验证耗时与内存。</p><ul><li>每个密码使用独立随机 salt，交给成熟库生成并编码到哈希记录中。</li><li>保存算法与成本参数，用户成功登录时可渐进升级旧哈希。</li><li>SHA-256、MD5 等快速摘要不适合直接保存人类密码。</li><li>旧 bcrypt 系统要特别检查库的 72 字节边界；不要把字节限制误当成字符限制。</li><li>可选 pepper 与数据库分开保管，但轮换与故障处理更复杂，不能代替慢哈希。</li></ul><p>密码校验的内存需求大致随“单次成本 × 并行验证数”增长。例如每次约 19 MiB、100 次并行，仅算法配置对应的内存就约 1.9 GiB，还未计入进程开销。认证服务应在进入昂贵计算前做输入长度与流量限制，并控制验证并发。</p><h2 id="deng-lu-shi-bai-yu-zhang-hao-mei-ju" tabindex="-1">登录失败与账号枚举 <a class="header-anchor" href="#deng-lu-shi-bai-yu-zhang-hao-mei-ju" aria-label="Permalink to &quot;登录失败与账号枚举&quot;">​</a></h2><p>同一个公开错误可以覆盖“账号不存在”“密码错误”和“不可用于此登录方式”，内部记录分别保留原因。还需比较状态码、响应长度、耗时与恢复接口行为，不能只把文案统一。</p><p>不存在的账号可以走预先生成的哑元哈希验证，减少明显的时间分支；这只缩小差异，不能保证整条链路恒定时间。限流必须先于昂贵哈希，避免攻击者借不存在的账号消耗计算资源。</p><p>建议组合多个限流维度：</p><table tabindex="0"><thead><tr><th>维度</th><th>能限制什么</th><th>单独使用的缺点</th></tr></thead><tbody><tr><td>IP、网络段</td><td>单来源高频尝试</td><td>共享出口误伤、代理轮换</td></tr><tr><td>规范化账号标识</td><td>分布式撞同一个账号</td><td>攻击者可能恶意锁定受害者</td></tr><tr><td>设备与风险信号</td><td>自动化与异常行为</td><td>可伪造、涉及隐私与误判</td></tr><tr><td>全局资源预算</td><td>大规模流量耗尽验证服务</td><td>不能识别具体账号风险</td></tr></tbody></table><p>采用渐进退避、短期限制和强认证提升，通常比无限期锁号更容易恢复。错误密码次数清零、跨节点计数、时钟与缓存故障都要定义行为。<a href="https://cheatsheetseries.owasp.org/cheatsheets/Authentication_Cheat_Sheet.html#login-throttling" target="_blank" rel="noreferrer">OWASP Authentication</a>讨论了登录限流与锁定策略。</p><h2 id="yan-zheng-ma-yao-you-yong-tu-he-shi-wu-bian-jie" tabindex="-1">验证码要有用途和事务边界 <a class="header-anchor" href="#yan-zheng-ma-yao-you-yong-tu-he-shi-wu-bian-jie" aria-label="Permalink to &quot;验证码要有用途和事务边界&quot;">​</a></h2><p>短信码、邮箱码和邮件链接都是短期凭据，需要绑定用途：注册码不能用来重置密码，登录码不能用来换绑其他账号。</p><p>建议记录 <code>challenge_id</code>、用途、目标标识或账号、过期时间、剩余尝试次数、消费时间与安全版本。重新发送时应规定旧码是否失效，不能让用户可用的码数无上限增长。</p><p>低熵数字码不能只用普通 SHA-256 摘要保护：数据库泄露后，攻击者可枚举全部短码。可以使用独立服务密钥参与 HMAC，并配合严格的过期、尝试次数和密钥隔离。高熵随机链接令牌可以只存摘要。TOTP 的共享种子则需要解密后参与验证，见 <a href="./mfa-passkey.html">MFA 设计</a>。</p><p>验证成功与消费需要原子完成。两个并发请求不能都读到“未使用”，再各自建立一个授权结果。可使用条件更新、行锁或等价的存储原子操作；重发接口同样需要频率与费用预算。</p><h2 id="mi-ma-chong-zhi-shi-wu" tabindex="-1">密码重置事务 <a class="header-anchor" href="#mi-ma-chong-zhi-shi-wu" aria-label="Permalink to &quot;密码重置事务&quot;">​</a></h2><p><a href="https://cheatsheetseries.owasp.org/cheatsheets/Forgot_Password_Cheat_Sheet.html" target="_blank" rel="noreferrer">OWASP Forgot Password</a>建议恢复令牌随机、短期有效、单次使用，并避免接口泄露账号存在性。恢复链接使用受信任的固定站点地址生成，不直接使用请求中未经验证的 <code>Host</code>。</p><p>下面聚焦用户取得恢复链接后的提交过程。图中“检查并消费”属于同一数据库事务，失败时不产生部分改密结果。</p>',22)),(a(),s(l,null,{default:r(()=>[A(o,{id:"mermaid-148",class:"mermaid",graph:"sequenceDiagram%0A%20%20%20%20autonumber%0A%20%20%20%20participant%20C%20as%20%E6%B5%8F%E8%A7%88%E5%99%A8%0A%20%20%20%20participant%20A%20as%20%E6%81%A2%E5%A4%8D%E6%9C%8D%E5%8A%A1%0A%20%20%20%20participant%20D%20as%20%E6%95%B0%E6%8D%AE%E5%BA%93%0A%20%20%20%20C-%3E%3EA%3A%20%E6%81%A2%E5%A4%8D%E4%BB%A4%E7%89%8C%E4%B8%8E%E6%96%B0%E5%AF%86%E7%A0%81%0A%20%20%20%20A-%3E%3EA%3A%20%E8%BE%93%E5%85%A5%E6%A3%80%E6%9F%A5%E3%80%81%E9%99%90%E6%B5%81%E4%B8%8E%E5%AF%86%E7%A0%81%E7%AD%96%E7%95%A5%E6%A0%A1%E9%AA%8C%0A%20%20%20%20A-%3E%3ED%3A%20BEGIN%EF%BC%8C%E9%94%81%E5%AE%9A%E6%8C%91%E6%88%98%E4%B8%8E%E8%B4%A6%E5%8F%B7%0A%20%20%20%20D--%3E%3EA%3A%20%E6%8C%91%E6%88%98%E7%8A%B6%E6%80%81%E4%B8%8E%E8%B4%A6%E5%8F%B7%E5%AE%89%E5%85%A8%E7%89%88%E6%9C%AC%0A%20%20%20%20alt%20%E6%8C%91%E6%88%98%E6%88%96%E8%B4%A6%E5%8F%B7%E6%A0%A1%E9%AA%8C%E5%A4%B1%E8%B4%A5%0A%20%20%20%20%20%20%20%20A-%3E%3ED%3A%20ROLLBACK%0A%20%20%20%20%20%20%20%20A--%3E%3EC%3A%20%E6%8B%92%E7%BB%9D%E9%87%8D%E7%BD%AE%0A%20%20%20%20else%20%E6%BB%A1%E8%B6%B3%E5%85%A8%E9%83%A8%E6%81%A2%E5%A4%8D%E6%9D%A1%E4%BB%B6%0A%20%20%20%20%20%20%20%20A-%3E%3ED%3A%20%E6%9B%B4%E6%96%B0%E5%AF%86%E7%A0%81%E5%93%88%E5%B8%8C%E4%B8%8E%E5%AE%89%E5%85%A8%E7%89%88%E6%9C%AC%0A%20%20%20%20%20%20%20%20A-%3E%3ED%3A%20%E6%B6%88%E8%B4%B9%E6%8C%91%E6%88%98%EF%BC%8C%E6%92%A4%E9%94%80%E6%97%A7%E7%99%BB%E5%BD%95%E8%B5%84%E6%A0%BC%0A%20%20%20%20%20%20%20%20A-%3E%3ED%3A%20%E5%86%99%E9%80%9A%E7%9F%A5%E4%B8%8E%E5%A4%B1%E6%95%88%E4%BA%8B%E4%BB%B6%E5%88%B0%20outbox%0A%20%20%20%20%20%20%20%20A-%3E%3ED%3A%20COMMIT%0A%20%20%20%20%20%20%20%20A--%3E%3EC%3A%20%E9%87%8D%E7%BD%AE%E5%AE%8C%E6%88%90%EF%BC%8C%E8%A6%81%E6%B1%82%E9%87%8D%E6%96%B0%E7%99%BB%E5%BD%95%0A%20%20%20%20end%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[n(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t('<p>挑战校验覆盖用途、有效期、消费状态与尝试限制，账号校验覆盖恢复资格及安全版本；版本增加后，该账号其他旧恢复请求也应失效。outbox 的投递发生在提交之后。</p><p>慢哈希可在事务前计算以缩短持锁时间，但事务内仍要重新检查所有决定有效性的条件。会话如果存于外部缓存，不能假设数据库提交与缓存删除具备原子性；通过安全版本检查、可靠事件和受限缓存时限补足，见<a href="./system-design.html">参考设计</a>。</p><p>恢复完成后要求用户重新登录；可发送安全通知，但不把新密码或恢复令牌写进通知日志。恢复页面不加载非必要第三方资源，配置适当的 Referrer 策略，并避免分析系统记录带令牌的 URL。</p><h2 id="mi-ma-xiu-gaiduan-xin-deng-lu-yu-ke-fu-hui-fu" tabindex="-1">密码修改、短信登录与客服恢复 <a class="header-anchor" href="#mi-ma-xiu-gaiduan-xin-deng-lu-yu-ke-fu-hui-fu" aria-label="Permalink to &quot;密码修改、短信登录与客服恢复&quot;">​</a></h2><p>已登录的密码修改应要求近期认证或等价证明，并区分“只退出其他设备”和“全部重新登录”。无论产品如何选择，都要更新安全状态并明确告知用户。</p><p>短信登录只依赖号码控制权，不能直接等价为高强度 MFA；存在换卡、转移、转发和号码回收风险。用于重要资产时，应提供更强认证方式并审查恢复规则。</p><p>客服恢复是高权限入口。应有独立审核、操作留痕、必要的延迟与异动通知；不能仅凭能搜索到的生日、订单截图或安全问题答案，直接移除原有 MFA。</p><h2 id="can-kao-zi-liao" tabindex="-1">参考资料 <a class="header-anchor" href="#can-kao-zi-liao" aria-label="Permalink to &quot;参考资料&quot;">​</a></h2><ul><li>NIST：<a href="https://pages.nist.gov/800-63-4/sp800-63b.html#passwordver" target="_blank" rel="noreferrer">SP 800-63B-4 §3.1.1 — Passwords</a></li><li>OWASP：<a href="https://cheatsheetseries.owasp.org/cheatsheets/Password_Storage_Cheat_Sheet.html" target="_blank" rel="noreferrer">Password Storage Cheat Sheet</a></li><li>OWASP：<a href="https://cheatsheetseries.owasp.org/cheatsheets/Authentication_Cheat_Sheet.html#login-throttling" target="_blank" rel="noreferrer">Authentication — Login Throttling</a></li><li>OWASP：<a href="https://cheatsheetseries.owasp.org/cheatsheets/Forgot_Password_Cheat_Sheet.html" target="_blank" rel="noreferrer">Forgot Password Cheat Sheet</a></li></ul>',9))])}const C=E(d,[["render",p]]);export{f as __pageData,C as default};
